-- PRD v1.0 foundation. SQLite / Cloudflare D1.
PRAGMA foreign_keys=ON;
CREATE TABLE users(id TEXT PRIMARY KEY,email TEXT NOT NULL UNIQUE,display_name TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE organizations(id TEXT PRIMARY KEY,legal_name TEXT NOT NULL,legal_form TEXT NOT NULL CHECK(legal_form IN ('eenmanszaak','bv','vof','other')),kvk_number TEXT,vat_id TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE memberships(org_id TEXT NOT NULL,user_id TEXT NOT NULL,role TEXT NOT NULL CHECK(role IN ('owner','admin','bookkeeper','reviewer','submitter')),status TEXT NOT NULL DEFAULT 'active' CHECK(status IN ('active','invited','revoked')),PRIMARY KEY(org_id,user_id),FOREIGN KEY(org_id) REFERENCES organizations(id),FOREIGN KEY(user_id) REFERENCES users(id));
CREATE TABLE consents(id TEXT PRIMARY KEY,org_id TEXT NOT NULL,user_id TEXT NOT NULL,kind TEXT NOT NULL,scope TEXT NOT NULL,granted_at TEXT NOT NULL,revoked_at TEXT,FOREIGN KEY(org_id) REFERENCES organizations(id));
CREATE TABLE oauth_connections(id TEXT PRIMARY KEY,org_id TEXT NOT NULL,provider TEXT NOT NULL,scopes TEXT NOT NULL,encrypted_token_ref TEXT NOT NULL,expires_at TEXT,revoked_at TEXT,FOREIGN KEY(org_id) REFERENCES organizations(id));
CREATE TABLE documents(id TEXT PRIMARY KEY,org_id TEXT NOT NULL,sha256 TEXT NOT NULL,object_key TEXT NOT NULL,mime_type TEXT NOT NULL,source TEXT NOT NULL,uploaded_by TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'pending',deleted_at TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(org_id) REFERENCES organizations(id),UNIQUE(org_id,sha256));
CREATE TABLE invoice_extractions(id TEXT PRIMARY KEY,org_id TEXT NOT NULL,document_id TEXT NOT NULL,model_version TEXT,extracted_json TEXT NOT NULL,confidence REAL,review_status TEXT NOT NULL DEFAULT 'pending',created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(org_id) REFERENCES organizations(id),FOREIGN KEY(document_id) REFERENCES documents(id));
CREATE TABLE bank_accounts(id TEXT PRIMARY KEY,org_id TEXT NOT NULL,iban_masked TEXT NOT NULL,currency TEXT NOT NULL DEFAULT 'EUR',FOREIGN KEY(org_id) REFERENCES organizations(id));
CREATE TABLE bank_imports(id TEXT PRIMARY KEY,org_id TEXT NOT NULL,document_id TEXT NOT NULL,imported_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(org_id) REFERENCES organizations(id),FOREIGN KEY(document_id) REFERENCES documents(id));
CREATE TABLE bank_transactions(id TEXT PRIMARY KEY,org_id TEXT NOT NULL,bank_import_id TEXT NOT NULL,bank_account_id TEXT,booked_on TEXT NOT NULL,amount_cents INTEGER NOT NULL,currency TEXT NOT NULL,counterparty_masked TEXT,reference TEXT,FOREIGN KEY(org_id) REFERENCES organizations(id),FOREIGN KEY(bank_import_id) REFERENCES bank_imports(id));
CREATE TABLE reconciliation_matches(id TEXT PRIMARY KEY,org_id TEXT NOT NULL,transaction_id TEXT NOT NULL,invoice_extraction_id TEXT,decision TEXT NOT NULL,reviewed_by TEXT,FOREIGN KEY(org_id) REFERENCES organizations(id));
CREATE TABLE review_tasks(id TEXT PRIMARY KEY,org_id TEXT NOT NULL,kind TEXT NOT NULL,resource_id TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'open',assigned_to TEXT,FOREIGN KEY(org_id) REFERENCES organizations(id));
CREATE TABLE review_decisions(id TEXT PRIMARY KEY,org_id TEXT NOT NULL,task_id TEXT NOT NULL,user_id TEXT NOT NULL,decision TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(org_id) REFERENCES organizations(id));
CREATE TABLE tax_rule_versions(id TEXT PRIMARY KEY,jurisdiction TEXT NOT NULL,version TEXT NOT NULL,effective_from TEXT NOT NULL,checksum TEXT NOT NULL);
CREATE TABLE tax_periods(id TEXT PRIMARY KEY,org_id TEXT NOT NULL,period_start TEXT NOT NULL,period_end TEXT NOT NULL,kind TEXT NOT NULL DEFAULT 'BTW',UNIQUE(org_id,period_start,period_end,kind),FOREIGN KEY(org_id) REFERENCES organizations(id));
CREATE TABLE filing_drafts(id TEXT PRIMARY KEY,org_id TEXT NOT NULL,tax_period_id TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'DRAFT',rules_version_id TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(org_id) REFERENCES organizations(id),FOREIGN KEY(tax_period_id) REFERENCES tax_periods(id));
CREATE TABLE filing_line_items(id TEXT PRIMARY KEY,org_id TEXT NOT NULL,filing_draft_id TEXT NOT NULL,field_code TEXT NOT NULL,amount_cents INTEGER NOT NULL,evidence_json TEXT NOT NULL DEFAULT '[]',FOREIGN KEY(org_id) REFERENCES organizations(id),FOREIGN KEY(filing_draft_id) REFERENCES filing_drafts(id));
CREATE TABLE filing_snapshots(id TEXT PRIMARY KEY,org_id TEXT NOT NULL,filing_draft_id TEXT NOT NULL,payload_json TEXT NOT NULL,payload_sha256 TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(org_id) REFERENCES organizations(id),FOREIGN KEY(filing_draft_id) REFERENCES filing_drafts(id));
CREATE TABLE approvals(id TEXT PRIMARY KEY,org_id TEXT NOT NULL,snapshot_id TEXT NOT NULL,approved_by TEXT NOT NULL,approved_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,statement_version TEXT NOT NULL,FOREIGN KEY(org_id) REFERENCES organizations(id),FOREIGN KEY(snapshot_id) REFERENCES filing_snapshots(id));
CREATE TABLE filing_authorizations(id TEXT PRIMARY KEY,org_id TEXT NOT NULL,snapshot_id TEXT NOT NULL,channel TEXT NOT NULL,status TEXT NOT NULL,proof_ref TEXT,verified_at TEXT,FOREIGN KEY(org_id) REFERENCES organizations(id),FOREIGN KEY(snapshot_id) REFERENCES filing_snapshots(id));
CREATE TABLE submission_attempts(id TEXT PRIMARY KEY,org_id TEXT NOT NULL,snapshot_id TEXT NOT NULL,adapter TEXT NOT NULL,idempotency_key TEXT NOT NULL,status TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE(org_id,idempotency_key),FOREIGN KEY(org_id) REFERENCES organizations(id));
CREATE TABLE submission_events(id TEXT PRIMARY KEY,org_id TEXT NOT NULL,attempt_id TEXT NOT NULL,status TEXT NOT NULL,recorded_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(org_id) REFERENCES organizations(id),FOREIGN KEY(attempt_id) REFERENCES submission_attempts(id));
CREATE TABLE official_receipts(id TEXT PRIMARY KEY,org_id TEXT NOT NULL,attempt_id TEXT NOT NULL,receipt_ref TEXT NOT NULL,payload_json TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(org_id) REFERENCES organizations(id),FOREIGN KEY(attempt_id) REFERENCES submission_attempts(id));
CREATE TABLE audit_events(id TEXT PRIMARY KEY,org_id TEXT NOT NULL,actor_id TEXT NOT NULL,action TEXT NOT NULL,resource_type TEXT NOT NULL,resource_id TEXT NOT NULL,metadata_json TEXT NOT NULL DEFAULT '{}',occurred_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(org_id) REFERENCES organizations(id));
CREATE TABLE notifications(id TEXT PRIMARY KEY,org_id TEXT NOT NULL,user_id TEXT NOT NULL,kind TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'pending',FOREIGN KEY(org_id) REFERENCES organizations(id));
CREATE TABLE subscriptions(id TEXT PRIMARY KEY,org_id TEXT NOT NULL,provider_ref TEXT,plan TEXT NOT NULL,status TEXT NOT NULL,FOREIGN KEY(org_id) REFERENCES organizations(id));
CREATE INDEX idx_docs_org ON documents(org_id,created_at);
CREATE INDEX idx_tx_org ON bank_transactions(org_id,booked_on);
CREATE INDEX idx_filing_org ON filing_drafts(org_id,tax_period_id);
CREATE INDEX idx_audit_org ON audit_events(org_id,occurred_at);
